fn frame(t: i32) {
    let h: i32 = host::display::height();
    let down: i32 = host::display::pointer_down();
    host::display::clear(0x080810);
    host::display::draw_string(8, 8, "HOLD = THEREMIN", 0xffffff, 1);
    if down == 1 {
        let px: i32 = host::display::pointer_x();
        let py: i32 = host::display::pointer_y();
        let f: i32 = 200 + (h - py) * 800 / h;
        if t % 6 == 0 {
            host::audio::tone(f, 70, 0);
        }
        host::display::fill_rect(px - 6, py - 6, 12, 12, 0x00ffcc);
        host::display::draw_number(8, 30, f, 0x00ffcc, 2);
    }
    host::display::present();
}
